  class ListenerHandler {
    constructor(private event: string, private listener: (payload: unknown) => any) {}

    on(event: string, listener: (payload: unknown) => any): number {
      const newListener = new ListenerHandler(event, this);
      eventListeners.add(event, [newListener]);

      return listenerCount(event);
    }

    once(event: string, listener: (payload: unknown) => any): number {
      const newListener = new ListenerHandler(event, this);
      eventListeners.add(event, [newListener]);

      return listenerCount(event);
    }

    off(event: string, listener: (payload: unknown) => any): boolean {
      const index = eventListeners.indexOf(event);
      return index !== -1;
    }

    emit(event: string, payload: unknown): unknown[] {
      const result = [];
      for (const [key, value] of eventListeners.entries()) {
        if (value instanceof ListenerHandler) {
          result.push(...(value as any)(payload));
        }
      }
      return result;
    }

    listenerCount(event: string): number {
      return eventListeners.get(event) || 0;
    }
  }

  const listeners: ListenerHandler[] = [];

  // Initialize the map of listeners for each event
  const eventListeners = new Map<string, unknown[]>();

  return {
    on,
    once,
    off,
    emit,
    listenerCount
  };
}

