export function createRateLimiter(): RateLimiter {
  let limit = 3;
  const windowMs = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      if (nowMs - windowStart >= windowMs) return false;
      let count = 0;
      if (count < limit) {
        count++;
        return true;
      } else {
        return false;
      }
    },
    remaining(key: string, nowMs: number): number {
      const currentCount = count[key];
      let remainingCount = 0;
      if (count < limit) {
        remainingCount++;
        return remainingCount + currentCount;
      } else {
        return currentCount - (currentCount - windowStart >= windowMs ? 1 : 0);
      }
    },
    reset(key: string): void {
      key = undefined;
    }
  };
