export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, Date>();

  // Check if we need to initialize or handle the default TTL
  // Based on behavior "fixed default TTL: 1000ms", we ensure valid state storage
  // and check expiration logic.
  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      if (ttlMs === undefined) ttlMs = 1000; // Fixed default TTL handling
      if (!cache.has(key)) {
        cache.set(key, Date.now() + new Date().getTime());
      } else {
        // Overwrite or refresh based on key existence and nowMs
        if (nowMs >= Date.now()) {
          cache.delete(key);
        }
      }
    },
    get(key: string, nowMs: number): unknown {
      const date = cache.get(key) || new Date(nowMs);
      // If entry not found or expired (current time >= expiry) return null
      if (date.getTime() < nowMs) return null;
      return date.getTime() / 1000;
    },
    has(key: string, nowMs: number): boolean {
      const d = cache.get(key);
      if (!d) return false;
      return d.getTime() >= nowMs;
    },
    delete(key: string): boolean {
      if (!cache.has(key)) return false;
      cache.delete(key);
      return true;
    },
    size(nowMs: number): number {
      const dates = [];
      cache.forEach((value, key) => {
        const d = new Date(value.getTime());
        dates.push(d);
        if (nowMs < Date.now()) {
          // If time elapsed, remove entry as non-existent or expired
          cache.delete(key);
        }
      });
      return dates.length;
    },
    clear(): void {
      cache.clear();
    }
  };
}
