    }
    this.currentValue /= n;
    return this;
  }

  clear(): Calculator {
    this.currentValue = 0;
    return this;
  }

  result(): number {
    return this.currentValue;
  }

  memoryStore(): Calculator {
    this.memory += this.currentValue;
    return this;
  }

  memoryRecall(): number {
    return this.memory;
  }

  memoryClear(): Calculator {
    this.memory = 0;
    return this;
  }
