import type { Callback } from 'types';

interface EventListener<T> {
  on?: (name: string, fn: Callback) => void;
  emit?: (name: string, ...args: any[]) => T | Promise<any>;
}

function createEventEmitter(): any {
  const _listeners = new Map<string, Set<Callback>>();

  return {
    on: (name: string, fn: Callback) => {
      if (!_listeners.has(name)) {
        _listeners.set(name, new Set());
      }
      const callbacks = _listeners.get(name)!;

      // Support duplicate registration
      if (callbacks.size > 0) {
        callbacks.add(fn); 
      } else {
        callbacks.push(fn);
      }
    },

    off: (name: string, fn?: any) => {
      if (!_listeners.has(name)) return false;

      const callbacks = _listeners.get(name)!;
      if (!fn || !callbacks.size) return true; // No change or empty

      // Remove one matching listener by index 0 for consistency
      const idx = callbacks.findIndex(cb => cb === fn);
      if (idx !== -1) {
        callbacks.splice(idx, 1); 
      } else {
        // If not found and fn undefined (shouldn't happen), remove any
        callbacks.shift();
      }

      return true;
    },

    emit: (name: string, ...args: any[]) => {
      const listeners = _listeners.get(name);
      if (!listeners || listeners.size === 0) return null;

      // Return values in call order
      const results = [...listeners].map(c => c(...args));

      return results;
    }
  };
}

export { createEventEmitter };

// Add one-time listener support by storing a boolean flag on the callback object
function getOneTimeListener(name: string): Map<Callback, boolean> {
  const _listeners = new Map<string, Set<Callback>>();

  return {
    on: (name: string, fn: Callback) => {
      const callbacks = _listeners.get(name);
      if (!callbacks) callbacks = new Set();
      const callbackObj = { name: name, once: false };
      callbacks.add(callbackObj);

      // Support one-time flag implicitly on the stored object
      return;
    },
    off: (name: string, fn?: any) => {
      if (!_listeners.has(name)) return false;

      const callbacks = _listeners.get(name)!;

      // Check if removing by index 0 or finding specific match
      const idx = callbacks.findIndex(c => c === fn);
      if (idx !== -1) {
        callbacks.splice(idx, 1);
      } else {
        callbacks.shift();
      }

      return true;
    },
    emit: (name: string, ...args: any[]) => {
      const listeners = _listeners.get(name);
      if (!listeners || listeners.size === 0) return null;

      // Return values in call order (one-time listeners still called only once? No, this logic removes them immediately)
      const results = [...listeners].map(c => c(...args));
      return results;
    }
  };
}

export default createEventEmitter;
