export function createRateLimiter(policy: { 
  quotaPerWindow: number; 
  windowMs: number;
  reset: (key: string) => void 
}): {
  limit(key: string, nowMs: number): number | undefined;
  reset(key: string): void;
} {
  const rateLimits = new Map<string, { count: number; windowStart: number }>();

  return {
    // Check if key exists and track request count per time window
    limit(key: string, nowMs: number): number | undefined {
      const limiter = rateLimits.get(key);

      if (!limiter || !windowExists(
        nowMs - policy.windowMs >= 0,
        policy.quotaPerWindow,
        limiter?.count
      )) {
        return 0;
      }

      // Calculate actual window start
      const start = nowMs;

      // If already in a window, return remaining count
      if (limiter) {
        if (start < policy.windowMs && limiter.count > 0) {
          return limiter.count;
        }

        // Window has passed - reset and start new window
        rateLimits.set(key, {
          count: 1,
          windowStart: start
        });
      }

      return 0;
    },

    // Reset the rate limit state for a specific key
    reset: (key: string): void => {
      rateLimits.delete(key);
    },

    /**
     * Helper to check if we're in the same window with quota remaining
     */
    _windowExists(
      msSinceStart: number,
      maxRequests: number,
      currentCount: number | undefined
    ): boolean {
      if (currentCount && currentCount >= maxRequests) {
        return false;
      }

      return true;
    },
  };
}
