interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

class InternalRateLimiter {
  private _allowedCount = new Map<string, number>();
  private _windowStart = new Map<string, number>();

  static readonly limit = 3;
  static readonly windowMs = 1000;

  allow(key: string, nowMs: number): boolean {
    const windowKey = `key_${key}`;
    const allowedCount = this._allowedCount.get(windowKey) || 0;
    const currentWindowStart = this._windowStart.get(windowKey);

    // If no window start yet or time difference is >= windowMs, it's a fresh window
    if (currentWindowStart !== undefined && nowMs - currentWindowStart < 1000) {
      // Window not expired
      const count = this._allowedCount.get(windowKey) || 0;
      if (count < InternalRateLimiter.limit) {
        this._allowedCount.set(windowKey, count + 1);
        return true;
      }
    }

    // Window has expired or no window tracked, reset for key
    const remaining = this._windowStart.get(key);
    if (remaining !== undefined && nowMs - remaining >= InternalRateLimiter.windowMs) {
      // Start fresh window
      this._allowedCount.set(windowKey, 0);
    } else {
      // No valid window start or window expired? Reset logic per key requires state check.
      // If current time is outside window, clear count.
      this._windowStart.set(key, nowMs);
      this._allowedCount.set(windowKey, 0);
    }

    return false;
  }

  remaining(key: string, nowMs: number): number {
    const windowKey = `key_${key}`;
    const count = this._allowedCount.get(windowKey) || 0;
    return Math.max(0, InternalRateLimiter.limit - count);
  }

  reset(key: string): void {
    const windowKey = `key_${key}`;
    if (this._windowStart.has(key)) {
      this._windowStart.delete(key);
    }
    if (this._allowedCount.has(windowKey)) {
      this._allowedCount.delete(windowKey);
    }
  }
}

export function createRateLimiter(): RateLimiter {
  return new InternalRateLimiter();
}
