  const todoStore: Array<{ id: number; text: string; completed: boolean }> = [];

  function getNextId(): number {
    return todoIdCounter++;
  }

  const addTodo = (text: string): { id: number; text: string; completed: boolean } => {
    const newTodo = { 
      id: getNextId(), 
      text, 
      completed: false 
    };
    todoStore.push(newTodo);
