    return [...todoStore];
  };

  const listCompleted = (): Array<{ id: number; text: string; completed: boolean }> => {
    return todoStore.filter(t => t.completed);
  };

  const listPending = (): Array<{ id: number; text: string; completed: boolean }> => {
    return todoStore.filter(t => !t.completed);
  };

  const clearCompleted = () => {
    todoStore = todoStore.filter(t => !t.completed);
  };

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
