interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

interface TodoApp {
  addTodo(text: string): Todo;
  getTodo(id: number): Todo | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): Todo[];
  listCompleted(): Todo[];
  listPending(): Todo[];
  clearCompleted(): void;
}

export function createTodoApp(): TodoApp {
  const todoMap = new Map();
  let idCounter = 0;

  return {
    addTodo: (text: string): Todo => {
      const nextId = ++idCounter;
      const newTodo: Todo = { id: nextId, text, completed: false };
      todoMap.set(nextId, newTodo);
      return newTodo;
    },
    getTodo: (id: number): Todo | undefined => todoMap.get(id),
    toggleTodo: (id: number): void => {
      const todo = todoMap.get(id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },
    deleteTodo: (id: number): boolean => {
      const todo = todoMap.get(id);
      if (todo) {
        todoMap.delete(id);
        return true;
      }
      return false;
    },
    listTodos: () => Array.from(todoMap.values()),
    listCompleted: () => Array.from(todoMap.values()).filter(t => t.completed),
    listPending: () => Array.from(todoMap.values()).filter(t => !t.completed),
    clearCompleted: () => {
      const keys = new Set<number>(todoMap.keys());
      for (const key of keys) {
        const todo = todoMap.get(key);
        if (todo?.completed === true) todoMap.delete(key);
      }
    }
  };
