export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, object>();

  // Store entry structure
  const now = Date.now();

  return {
    set(key: string, value: unknown, ttlMs?: number): void {
      let expiresAt: number;
      if (ttlMs === undefined || ttlMs === null) {
        expiresAt = now + 1000; // Default TTL 1s per spec logic for immediate check, but interface defaults to 1000ms here
        // Wait, spec says "Fixed default TTL: 1000ms"
        // So if ttlMs is not provided (undefined), it should be 1000
        expiresAt = now + ttlMs!;
      } else {
        expiresAt = now + ttlMs;
      }

      const entry: object = { value, expiresAt };
      cache.set(key, entry);
    },

    get(key: string): unknown {
      if (!cache.has(key)) {
        return undefined; // This matches "Storing undefined is valid... has(...) returns boolean"
      }
      const entry = cache.get(key)!;
      const isExpired = entry.expiresAt <= now;
      return isExpired ? undefined : entry.value;
    },

    has(key: string): boolean {
      if (cache.has(key)) {
        return true;
      }
      return false; // If not in map, not in cache
    },

    delete(key: string): boolean {
      const entry = cache.get(key);
      if (!entry) return false;
      cache.delete(key);
      return true;
    },

    clear(): void {
      cache.clear();
    },

    size(nowMs: number): number {
      // Check only non-expired entries?
      // Wait, interface `size` should count non-expired entries based on nowMs check?
      // If the entry expiresAt > nowMs, it counts. Else not.
      const expiredKeys = [];
      cache.forEach((_, key) => {
        const entry = cache.get(key);
        if (entry && entry.expiresAt > now) {
          size++;
        } else {
          expiredKeys.push(key);
        }
      });

      // Return count of non-expired entries
      // But this requires knowing if an entry is present in the map.
      // The interface definition `size` takes `nowMs`.
      // I need to track all keys currently in map, then check expiration.
      // Actually, since this function returns an object with methods...
      // To implement size without global state across calls:
      // We iterate over cache. If entry is present and its expiresAt > now, count it.

      let count = 0;
      for (const [key, _] of cache.entries()) {
        if (_!.expiresAt > nowMs) count++;
      }
      return count;
    }
  };
}
