export function createRateLimiter(): {
  allow(key: string, nowMs: number): boolean;
  reset(key: string): void;
} {
  const _history = new Map<string, number[]>();

  return {
    allow(key: string, nowMs: number) {
      const history = _history.get(key);
      // Ensure we have an array reference
      let timestamps: number[] = history || [];

      // Filter for valid window (last 1000ms)
      const cutoff = nowMs - 1000;
      const activeRequests = timestamps.filter(t => t >= cutoff);

      // Check quota (max 3 requests per window)
      if (activeRequests.length < 3) {
        // Allow request
        timestamps.push(nowMs);
        _history.set(key, [...timestamps]);
        return true;
      } else {
        // Deny request
        return false;
      }
    },

    reset(key: string): void {
      _history.delete(key);
    }
  };
}
