const LIMIT = 3;
const WINDOW_MS = 1000;

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { windowStart: number; remaining: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let current = state.get(key);

      if (!current) {
        current = {
          windowStart: nowMs,
          remaining: LIMIT
        };
        state.set(key, current);
      }

      const elapsed = nowMs - current.windowStart;
      if (elapsed >= WINDOW_MS) {
        current.windowStart = nowMs;
        current.remaining = LIMIT;
      }

      if (current.remaining > 0) {
        current.remaining--;
        state.set(key, current);
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      let current = state.get(key);

      if (!current) {
        current = {
          windowStart: nowMs,
          remaining: LIMIT
        };
        state.set(key, current);
      }

      const elapsed = nowMs - current.windowStart;
      if (elapsed >= WINDOW_MS) {
        current.windowStart = nowMs;
        current.remaining = LIMIT;
      }

      return current.remaining;
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}
