interface TodoApp {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

export function createTodoApp(): TodoApp {
  const todos = new Map<number, Todo>();
  let nextId = 0;

  return {
    addTodo: (text: string): Todo => {
      nextId++;
      const todo: Todo = { id: nextId, text, completed: false };
      todos.set(nextId, todo);
      return todo;
    },
    getTodo: (id: number): Todo | undefined => {
      return todos.get(id);
    },
    toggleTodo: (id: number): void => {
      const todo = todos.get(id);
      if (todo !== undefined) {
        todo.completed = !todo.completed;
      }
    },
    deleteTodo: (id: number): boolean => {
      if (todos.has(id)) {
        todos.delete(id);
        return true;
      }
      return false;
    },
    listTodos: (): Todo[] => {
      return Array.from(todos.values());
    },
    listCompleted: (): Todo[] => {
      return Array.from(todos.entries())
        .filter(([, todo]) => todo.completed)
        .map(([, todo]) => todo);
    },
    listPending: (): Todo[] => {
      return Array.from(todos.entries())
        .filter(([, todo]) => !todo.completed)
        .map(([, todo]) => todo);
    },
    clearCompleted: (): void => {
      const idsToDelete = new Set<number>();
      for (const [id, todo] of todos.entries()) {
        if (todo.completed) {
          idsToDelete.add(id);
        }
      }
      for (const id of idsToDelete) {
        todos.delete(id);
      }
    },
  };
}
