      store.set(key, { value, expiresAt });
    },
    get(key: string, nowMs: number) {
      const entry = store.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number) {
      const entry = store.get(key);
      return entry !== undefined && nowMs < entry.expiresAt;
    },
    delete(key: string) {
      return store.delete(key);
    },
    size(nowMs: number) {
      let count = 0;
      for (const entry of store.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear() {
      store.clear();
    }
  };
