interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

const DEFAULT_TTL_MS = 1000;

export function createTtlCache(): TtlCache {
  const entries = new Map<string, { value: unknown | undefined; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const entryExists = entries.has(key);
      const expiresAt = nowMs + (ttlMs !== undefined ? ttlMs : DEFAULT_TTL_MS);

      // Overwrite existing value and refresh expiration time
      entries.set(key, { value: value as unknown, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (entry === undefined) return undefined;

      // Check expiration based on provided nowMs
      if (nowMs >= entry.expiresAt) {
        return undefined;
      }

      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      if (entry === undefined) return false;

      // Check expiration based on provided nowMs
      if (nowMs >= entry.expiresAt) {
        return false;
      }

      return true;
    },

    delete(key: string): boolean {
      const exists = entries.delete(key);
      return exists;
    },

    size(nowMs: number): number {
      let count = 0;
      for (const [_, entry] of entries.entries()) {
        if (nowMs >= entry.expiresAt) continue; // Skip expired entries
        count++;
      }
      return count;
    },

    clear(): void {
      entries.clear();
    }
  };
}
