type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>()

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      const list = listeners.get(event)!
      list.push({ fn: listener, once: false })
      return list.length
    },
    once(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      const list = listeners.get(event)!
      list.push({ fn: listener, once: true })
      return list.length
    },
    off(event, listener) {
      const list = listeners.get(event)
      if (!list) return false
      const index = list.findIndex((item) => item.fn === listener)
      if (index !== -1) {
        list.splice(index, 1)
        return true
      }
      return false
    },
    emit(event, payload) {
      const list = listeners.get(event)
      if (!list) return []
      const results: unknown[] = []
      for (let i = list.length - 1; i >= 0; i--) {
        const item = list[i]
        const res = item.fn(payload)
        results.push(res)
        if (item.once) {
          list.splice(i, 1)
        }
      }
      return results
    },
    listenerCount(event) {
      const list = listeners.get(event)
      return list ? list.length : 0
    },
  } as EventEmitter
}
