export function createRateLimiter(): {
    allow: (key: string, nowMs: number) => boolean;
    reset: (key: string) => void;
} {
    const maxRequests = 3;
    const windowSizeMs = 1000;

    // Map to store rate limit state per key.
    // Key -> { count: number, windowStart: number }
    const store = new Map<string, { count: number; windowStart: number }>();

    return {
        allow: (key: string, nowMs: number) => {
            // Calculate the start of the current fixed time window
            const windowStart = Math.floor(nowMs / windowSizeMs) * windowSizeMs;

            let state = store.get(key);

            // Check if we are in a fresh window or key does not exist
            // If window has elapsed (windowStart changed), reset state to 0.
            if (!state || state.windowStart !== windowStart) {
                store.set(key, { count: 0, windowStart });
                return true;
            }

            // Check quota for current window
            if (state.count < maxRequests) {
                state.count++;
                return true;
            }

            return false;
        },
        reset: (key: string) => {
            store.delete(key);
        },
    };
}
