```typescript
type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const storage = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  return {
    on(event, listener) {
      if (!storage.has(event)) {
        storage.set(event, []);
      }
      const list = storage.get(event)!;
      list.push({ fn: listener, once: false });
      return list.length;
    },

    once(event, listener) {
      if (!storage.has(event)) {
        storage.set(event, []);
      }
      const list = storage.get(event)!;
      list.push({ fn: listener, once: true });
      return list.length;
    },

    off(event, listener) {
      const list = storage.get(event);
      if (!list) return false;

      const index = list.findIndex((entry) => entry.fn === listener);
      if (index === -1) return false;

      list.splice(index, 1);
      if (list.length === 0) {
        storage.delete(event);
      }
      return true;
    },

    emit(event, payload) {
      const list = storage.get(event) || [];
      const results: unknown[] = [];
      const removeIndices: number[] = [];

      for (let i = 0; i < list.length; i++) {
        const entry = list[i];
        results.push(entry.fn(payload));
        if (entry.once) {
          removeIndices.push(i);
        }
      }

      for (let i = removeIndices.length - 1; i >= 0; i--) {
        list.splice(removeIndices[i], 1);
      }

      if (list.length === 0) {
        storage.delete(event);
      }

      return results;
    },

    listenerCount(event) {
      return storage.get(event)?.length || 0;
    },
  };
}
