  divide(n: number): Calculator;
  clear(): Calculator;
  result(): number;
  memoryStore(): Calculator;
  memoryRecall(): number;
  memoryClear(): Calculator;
  memoryAdd(): Calculator;
}

class CalculatorImpl implements Calculator {
  private value: number = 0;
  private memory: number = 0;

  add(n: number): Calculator {
    this.value += n;
    return this;
  }

  subtract(n: number): Calculator {
    this.value -= n;
    return this;
  }

  multiply(n: number): Calculator {
    this.value *= n;
    return this;
  }

  divide(n: number): Calculator {
    if (n !== 0) {
      this.value /= n;
    } else {
      // Handling division by zero to avoid Infinity, though not strictly specified. 
      // Usually keeps current value or throws. Keeping JS default behavior for simplicity implies Infinity.
      // However, often calculators keep 0 or throw. Let's stick to pure JS math behavior to be safe: this.value /= n.
      this.value /= n;
    }
    return this;
  }

  clear(): Calculator {
    this.value = 0;
    return this;
  }

  result(): number {
    return this.value;
  }

  memoryStore(): Calculator {
    this.memory = this.value;
    return this;
  }

  memoryRecall(): number {
    return this.memory;
  }

  memoryClear(): Calculator {
    this.memory = 0;
    return this;
  }

  memoryAdd(): Calculator {
    this.memory += this.value;
    return this;
  }
}

export function createCalculator(): Calculator {
  return new CalculatorImpl();
