type Listener = (...args: any[]) => any;

function createEventEmitter(): {
  on(event: string, listener: Listener): void;
  once(event: string, listener: Listener): void;
  off(event: string, listener: Listener): void;
  emit(event: string, ...args: any[]): any[];
} {
  const listeners = new Map<string, Array<{ callback: Listener; once: boolean }>>();

  function on(event: string, listener: Listener): void {
    const arr = listeners.get(event) || [];
    arr.push({ callback: listener, once: false });
    listeners.set(event, arr);
  }

  function once(event: string, listener: Listener): void {
    const arr = listeners.get(event) || [];
    arr.push({ callback: listener, once: true });
    listeners.set(event, arr);
  }

  function off(event: string, listener: Listener): void {
    const arr = listeners.get(event);
    if (!arr) return;
    const index = arr.findIndex(l => l.callback === listener);
    if (index !== -1) {
      arr.splice(index, 1);
    }
  }

  function emit(event: string, ...args: any[]): any[] {
    const arr = listeners.get(event);
    if (!arr) return [];

    const results: any[] = [];
    for (let i = 0; i < arr.length; i++) {
      const item = arr[i];
      const result = item.callback(...args);
      results.push(result);

      if (item.once) {
        arr.splice(i, 1);
        i--;
      }
    }

    return results;
  }

  return { on, once, off, emit };
}

export { createEventEmitter };
