export function createRateLimiter() {
  const windowMs = 1000;
  const maxRequests = 3;
  const state = new Map<string, { startTime: number; count: number }>();

  return {
    check(key: string, nowMs: number): boolean {
      let entry = state.get(key);

      if (!entry || (nowMs - entry.startTime >= windowMs)) {
        entry = { startTime: nowMs, count: 0 };
        state.set(key, entry);
      }

      if (entry.count < maxRequests) {
        entry.count++;
        return true;
      }

      return false;
    },
    reset(key: string): void {
      state.delete(key);
    }
  };
}
