interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

const LIMIT = 3;
const WINDOW_MS = 1000;

export function createRateLimiter(): RateLimiter {
  const keys = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      let state = keys.get(key);
      if (!state) {
        state = { count: 0, windowStart: nowMs };
        keys.set(key, state);
      } else {
        if (nowMs - state.windowStart >= WINDOW_MS) {
          state.count = 0;
          state.windowStart = nowMs;
        }
      }

      if (state.count < LIMIT) {
        state.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      let state = keys.get(key);
      if (!state) {
        return LIMIT;
      }

      if (nowMs - state.windowStart >= WINDOW_MS) {
        state.count = 0;
        state.windowStart = nowMs;
      }

      return Math.max(0, LIMIT - state.count);
    },
    reset(key: string): void {
      keys.delete(key);
    }
  };
}
