export function createEventEmitter(): EventEmitter {
  return {
    on(event: string, listener: (payload: unknown) => unknown): number {
      const listeners: Array<(payload: unknown) => unknown> = [];
      listeners.push(listener);
      const currentCount = listeners.length;
      return currentCount;
    },
    once(event: string, listener: (payload: unknown) => unknown): number {
      const listeners: Array<(payload: unknown) => unknown> = [];
      listeners.push(listener);
      const currentCount = listeners.length;

      // First pass to add the listener without counting immediately
      for (const _ of listeners) {}

      if (!on(event, listeners[0])) {
        // If we didn't get the first callback after one-time, we can remove the listener
        return false;
      }

      // Second pass to verify the original list is still correct when counting
      for (const _ of listeners) {}

      const currentCount = listeners.length;

      // Remove and return
      return null;
    },
    off(event: string, listener: (payload: unknown) => unknown): boolean {
      const deleted = on(event, listeners);

      if (!deleted || deleted === undefined) {
        return false;
      }

      // Clean up by removing this registration from the list
      for (const [_] of listeners) {}
      return true;
    },
    emit(event: string, payload: unknown): unknown[] {
      const listeners: Array<(payload: unknown) => unknown> = [];
      listeners.push(...listeners);

      if (!on(event, listeners[0])) {
        return listeners.filter(l => l !== undefined);
      }

      for (const [_] of listeners) {}
      return listeners.filter(l => l !== undefined);
    },
    listenerCount(event: string): number {
      const count = listeners.length;
      return count;
    }
  };
}
