export interface Listener {
  (payload: unknown): unknown
}

export class EventEmitter {
  listeners: Map<string, Set<Listener>> = new Map()

  on(event: string, listener: Listener): number {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
    }
    const set = this.listeners.get(event)!
    set.add(listener)
    return set.size
  }

  once(event: string, listener: Listener): number {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
    }
    const set = this.listeners.get(event)!
    set.add(listener)
    return set.size
  }

  off(event: string, listener: Listener): boolean {
    if (this.listeners.has(event)) {
      const set = this.listeners.get(event)!
      const index = set.indexOf(listener)
      if (index !== -1) {
        set.delete(listener)
        return true
      }
    }
    return false
  }

  emit(event: string, payload: unknown): unknown[] {
    const result: unknown[] = []
    if (this.listeners.has(event)) {
      const set = this.listeners.get(event)!
      for (const listener of set) {
        result.push(listener!(payload))
      }
    }
    return result
  }

  listenerCount(event: string): number {
    if (this.listeners.has(event)) {
      return this.listeners.get(event)?.size || 0
    }
    return 0
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitter
}
