interface RateLimitConfig {
  maxCalls: number;
  windowMs: number;
}

class RateLimiter {
  private static config: RateLimitConfig;
  private state = new Map<string, { pendingRequests: number; lastAccessedMs: number }>();

  constructor(config?: RateLimitConfig) {
    this.config = config ?? ({} as any);
  }

  keyExists(key: string): boolean {
    return this.state.has(this.key(key));
  }

  call(key: string): boolean {
    const state = this.state.get(key);

    if (!state) {
      return false;
    }

    let quotaRemaining = Math.max(0, this.config.maxCalls - state.pendingRequests);
    let quotaChecked = false;

    if (this.config.windowMs && !quotaChecked) {
      const now = Date.now();
      if (now < state.lastAccessedMs + this.config.windowMs / 1000) {
        // Window has not fully elapsed
        return true;
      } else {
        quotaChecked = true;
      }
    }

    let result: boolean;
    if (quotaRemaining > 0 || quotaChecked) {
      state.lastAccessedMs = Date.now();
      result = true;
    } else {
      // Window fully elapsed or all quota used - reset pending requests
      this.state.set(key, {
        pendingRequests: 0,
        lastAccessedMs: Date.now()
      });
      state.lastAccessedMs = Date.now();
    }

    if (result) {
      state.pendingRequests += 1;
    } else {
      // Window has expired - reset the key's pending count
      this.state.set(key, {
        pendingRequests: 0,
        lastAccessedMs: Date.now()
      });
    }

    return result;
  }

  reset(key: string) {
    if (this.keyExists(key)) {
      const newState = this.state.get(key);
      if (newState) {
        this.state.delete(key);
        return true;
      }
    }
    return false;
  }

  getQuotaUsed(key: string, windowMs?: number): number | null {
    let state = this.state.get(key);

    if (!windowMs || !this.config.windowMs) {
      return state ? state.pendingRequests : null;
    }

    const now = Date.now();
    const since = now - (state?.lastAccessedMs ?? this.config.windowMs / 1000);

    if (since < 0) {
      return undefined; // New key with no quota access
    }

    return state ? Math.min(this.config.maxCalls, state.pendingRequests + windowMs / 1000) : null;
  }
}

export function createRateLimiter() {
  return new RateLimiter();
}
