export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Set<EventCallback>>();

  function addListener(eventName: string, callback: EventCallback): void {
    if (!listeners.has(eventName)) {
      listeners.set(eventName, new Set());
    }
    // Add callback (store as is)
    (.listeners.get(eventName) as any).add(callback);
    (callback as { once?: boolean }).once = false;
  }

  function removeListener(eventName: string, callback: EventCallback): boolean {
    const eventListeners = listeners.get(eventName);
    if (!eventListeners) {
      return false;
    }
    const removed = (eventListeners as any).delete(callback);
    if ((eventListeners as any).size === 0 && removed) {
      listeners.delete(eventName);
    }
    return removed;
  }

  function emit(
    eventName: string,
    data?: any,
    once = false
  ): Array<any> {
    const callbackMap = listeners.get(eventName);
    if (!callbackMap) {
      return [];
    }

    const results = [];

    // Copy keys to avoid issues with Set modification during iteration
    const callbacks = [...(callbackMap as unknown[])] as EventCallback[];

    for (const callback of callbacks) {
      let result: any;

      try {
        // Call listener with data and eventName
        result = once ? callback(data, eventName) : callback();

        // If one-time listener succeeds and we called it manually, remove it
        // We need to track if the callback was removed after execution
      } catch (error) {
        console.error('Error in event listener:', error);
      }

      results.push(result);
    }

    return results;
  }

  function on(eventName: string, once = false): void {
    // Add listener logic here
  }

  return {
    on: (eventName: string, callback?: EventCallback | ((data: any, eventName?: string) => any)): void => {
      if (!eventName || !callback) return;

      const eventListeners = listeners.get(eventName);
      if (!eventListeners) {
        listeners.set(eventName, new Set());
      }

      // Add callback to the listeners set (we use a proxy approach to track it)
    },

    off: null as typeof removeListener,
    emit: emit as Function
  };
}

export type EventCallback = ((data?: any, eventName?: string) => any) | (() => any);

interface EventEmitter {
  on(eventName: string, callback?: EventCallback): void;
  off(eventName: string, callback?: EventCallback): boolean;
  emit(eventName: string, data?: any): Array<any>;
}
