export function createRateLimiter(): {
  acquire(key: string, nowMs: number): boolean;
  reset(key: string): void;
} {
  const limits: Map<string, RateLimiterState> = new Map();

  return {
    acquire(key: string, nowMs: number): boolean {
      if (!limits.has(key)) {
        limits.set(key, { lastRequestTimeMs: 0, requestCount: 0 });
      }

      const state = limits.get(key)!;
      const windowStart = Math.floor(state.lastRequestTimeMs / 1000) * 1000;
      const currentWindowEnd = windowStart + 1000;

      if (nowMs > currentWindowEnd) {
        state.lastRequestTimeMs = nowMs;
        state.requestCount = 1;
      } else {
        state.requestCount += 1;
      }

      return state.requestCount <= 3;
    },

    reset(key: string): void {
      const state = limits.get(key);
      if (state) {
        limits.set(key, { lastRequestTimeMs: 0, requestCount: 0 });
      }
    }
  };
}

interface RateLimiterState {
  lastRequestTimeMs: number;
  requestCount: number;
