const RATE_LIMIT = 3;
const WINDOW_MS = 1000;

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { startMs: number | null; count: number }>()

  return {
    allow(key: string, nowMs: number): boolean {
      let { startMs, count } = state.get(key) || { startMs: null, count: 0 }

      if (nowMs - startMs >= WINDOW_MS) {
        state.set(key, { startMs: nowMs, count: 0 })
        startMs = nowMs
        count = 0
      }

      if (!startMs) {
        state.set(key, { startMs: nowMs, count: 0 })
        startMs = nowMs
        count = 0
      }

      const updatedState = state.get(key) || { startMs: nowMs, count: 0 }

      if (nowMs - updatedState.startMs >= WINDOW_MS) {
        state.set(key, { startMs: nowMs, count: 0 })
        return false
      }

      count++
      state.set(key, updatedState)
      return true
    },
    remaining(key: string, nowMs: number): number | 0 {
      const { startMs, count } = state.get(key) || { startMs: null, count: 0 }

      if (nowMs - startMs >= WINDOW_MS) {
        state.set(key, { startMs: nowMs, count: 0 })
        return RATE_LIMIT
      }

      const isWindowValid = startMs !== null && nowMs - startMs < WINDOW_MS
      let remaining = RATE_LIMIT

      if (isWindowValid) {
        remaining = RATE_LIMIT - (state.get(key)?.count || 0)
      }

      return Math.max(0, remaining)
    },
    reset(key: string): void {
      state.delete(key)
    },
  }
}
