  }

  const addTodo = (text: string): Todo => {
    const id = getNextId();
    todos.set(id, { id, text, completed: false });
    return { id: id, text, completed: false };
  };

  const getTodo = (id: number): Todo | undefined => {
    return todos.get(id);
  };

  const toggleTodo = (id: number): void => {
    const todo = todos.get(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    if (!todos.has(id)) {
      return false;
    }
    todos.delete(id);
    return true;
  };

  const listTodos = (): Todo[] => {
    return Array.from(todos.entries()).map(([_, todo]) => todo);
  };

  const listCompleted = (): Todo[] => {
    return Array.from(todos.entries())
      .filter(([_, todo]) => todo.completed)
      .map(([_, todo]) => todo);
  };

  const listPending = (): Todo[] => {
    return Array.from(todos.entries())
      .filter(([_, todo]) => !todo.completed)
      .map(([_, todo]) => todo);
  };

  const clearCompleted = (): void => {
    const completedIds = Array.from(todos.entries()).filter(([_, todo]) => todo.completed).map(([id]) => id);
    for (const id of completedIds) {
      todos.delete(id);
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
