export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const entries = new Map<keyof Set<string>, { value?: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs) {
      if (typeof ttlMs !== 'number') {
        ttlMs = 1000; // default TTL is 1000ms
      }
      entries.set(key, { value: value, expiresAt: nowMs + ttlMs });
    },

    get(key, nowMs) {
      const entry = entries.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) return undefined; // entry expired
      return entry.value;
    },

    has(key, nowMs) {
      const entry = entries.get(key);
      if (!entry) return false;
      return nowMs < entry.expiresAt && entry.value !== undefined;
    },

    delete(key) {
      const existed = entries.has(key);
      entries.delete(key);
      return !!existed;
    },

    size(nowMs) {
      let count = 0;
      for (const key in entries) {
        if (!entries.hasOwnProperty(key)) continue;
        const entry = entries[key];
        if (nowMs < entry.expiresAt && entry.value !== undefined) {
          count++;
        }
      }
      return count;
    },

    clear() {
      entries.clear();
    }
  };
}
