interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

class TtlCacheImpl implements TtlCache {
  private cache: Map<string, { value: unknown; expiresAt: number }> = new Map()

  set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
    const currentExpiresAt = nowMs + (ttlMs === 0 ? this.calculateExpiration(nowMs) : ttlMs)
    cache.set(key, { value, expiresAt: currentExpiresAt })
  }

  get(key: string, nowMs: number): unknown {
    const entry = cache.get(key)
    if (!entry || nowMs >= entry.expiresAt) {
      return undefined
    }
    return entry.value
  }

  has(key: string, nowMs: number): boolean {
    const entry = cache.get(key)
    if (!entry) {
      return false
    }
    return nowMs < entry.expiresAt
  }

  delete(key: string): boolean {
    return cache.delete(key)
  }

  size(nowMs: number): number {
    let count = 0
    for (const [k, v] of cache.entries()) {
      if (nowMs < v.expiresAt) {
        count++
      }
    }
    return count
  }

  clear(): void {
    cache.clear()
  }
}

export function createTtlCache(): TtlCache {
  return new TtlCacheImpl()
}
