export interface RateLimitConfig {
  maxRequests: number;
  windowMs: number;
}

export function createRateLimiter(
  config?: Partial<RateLimitConfig>
): {
  check(key: string, nowMs?: number): boolean;
  reset(key: string): void;
} {
  const policy: RateLimitConfig = {
    maxRequests: 3,
    windowMs: 1000,
    ...config,
  };

  const stateMap = new Map<string, { windowStart: number; requestCount: number }>();

  function check(key: string, nowMs?: number): boolean {
    if (typeof nowMs !== 'number') {
      throw new Error('nowMs is required for deterministic rate limiting');
    }

    let state = stateMap.get(key);

    if (!state) {
      state = {
        windowStart: nowMs - policy.windowMs,
        requestCount: 0,
      };
      stateMap.set(key, state);
    }

    const threshold = state.windowStart + policy.windowMs;

    if (nowMs >= threshold) {
      state.windowStart = nowMs - policy.windowMs;
      state.requestCount = 0;
    }

    if (state.requestCount < policy.maxRequests) {
      state.requestCount++;
      return true;
    }

    return false;
  }

  function reset(key: string): void {
    stateMap.set(key, { windowStart: new Date().getTime(), requestCount: 0 });
  }

  return { check, reset };
}

export default createRateLimiter;
