export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const entries = new Map<string, Entry>();

  interface Entry {
    value: unknown;
    expiresAt: number;
  }

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const expiresAt = nowMs + (ttlMs ?? 1000);
    entries.set(key, { value, expiresAt });
  }

  function get(key: string, nowMs: number): unknown {
    const entry = entries.get(key);
    if (!entry) {
      return undefined;
    }
    // Entry is expired when nowMs >= expiresAt (strict expiration)
    if (nowMs >= entry.expiresAt) {
      entries.delete(key);
      return undefined;
    }
    return entry.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = entries.get(key);
    if (!entry) {
      return false;
    }
    // Has is true only for live entries (not expired)
    return nowMs < entry.expiresAt;
  }

  function delete(key: string): boolean {
    return entries.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const entry of entries.values()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  }

  function clear(): void {
    entries.clear();
  }

  return { set, get, has, delete, size, clear };
}
