export function createRateLimiter() {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;

  type KeyState = {
    windowStartMs: number;
    requestCount: number;
  };

  const state = new Map<string, KeyState>();

  function isAllowed(key: string, nowMs: number): boolean {
    const existingState = state.get(key);

    let currentState: KeyState | undefined = existingState;

    if (currentState) {
      const windowElapsed = nowMs - currentState.windowStartMs;
      if (windowElapsed >= WINDOW_MS) {
        currentState = {
          windowStartMs: nowMs,
          requestCount: 0,
        };
      }
    } else {
      currentState = {
        windowStartMs: nowMs,
        requestCount: 0,
      };
    }

    if (currentState.requestCount < MAX_REQUESTS) {
      currentState.requestCount++;
      state.set(key, currentState);
      return true;
    } else {
      state.set(key, currentState);
      return false;
    }
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { isAllowed, reset };
}
