  const events = new Map<string, EventState>();

  function getEventState(event: string): EventState | undefined {
    if (!events.has(event)) {
      return undefined;
    }
    return events.get(event)!;
  }

  function on(event: string, listener: Listener, once = false): void {
    const eventState = events.get(event) || {
      listeners: new Map(),
      queue: [],
    };
    if (!events.has(event)) {
      events.set(event, eventState);
    }
    eventState.listeners.set(listener, once);
    eventState.queue.push({ listener, isOnce: once });
  }

  function off(event: string | null, listener: Listener | null): void {
    if (event === null && listener === null) {
      events.clear();
      return;
    }

    if (!event || !listener) {
      return;
    }

    const eventState = getEventState(event);
    if (!eventState) {
      return;
    }

    let removed = false;
    const listenerEntries = Array.from(eventState.listeners.entries());

    for (const [list, isOnce] of listenerEntries) {
      if (list === listener && !removed) {
        eventState.listeners.delete(list);
        removed = true;
        break;
      }
    }

    if (!removed) {
      return;
    }

    eventState.queue = eventState.queue.filter(
      ({ listener: qListener, isOnce }) => !listenerEntries.some(([l]) => l === qListener && l.isOneTime !== undefined) || 
        Array.from(eventState.listeners.keys()).includes(qListener as Listener)
    );
  }

  function once(event: string, listener: Listener): void {
    on(event, listener, true);
  }

  function emit(event: string): unknown[] {
    const eventState = getEventState(event);
    if (!eventState || eventState.queue.length === 0) {
      return [];
    }

    const results: unknown[] = [];
    const queueToProcess = [...eventState.queue];

    for (const { listener, isOnce } of queueToProcess) {
      try {
        const result = listener();
        results.push(result);

        if (isOnce) {
          eventState.listeners.delete(listener);
        }
      } catch (error) {
        if (isOnce) {
          eventState.listeners.delete(listener);
        }
        throw error;
      }
    }

    const remainingQueue = queueToProcess.filter(({ listener, isOnce }) => 
      !isOnce || eventState.listeners.has(listener)
    );

    eventState.queue = remainingQueue;

    return results;
  }

  return { on, off, once, emit };
}

export { createEventEmitter };
