type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

function createEventEmitter(): EventEmitter {
  const listenersMap = new Map<string, Listener[]>()

  function on(event: string, listener: Listener): number {
    if (!listenersMap.has(event)) {
      listenersMap.set(event, [])
    }
    const eventListeners = listenersMap.get(event)!
    eventListeners.push(listener)
    return eventListeners.length
  }

  function once(event: string, listener: Listener): number {
    const wrappedListener = (payload: unknown): unknown => {
      off(event, wrappedListener)
      return listener(payload)
    }
    if (!listenersMap.has(event)) {
      listenersMap.set(event, [])
    }
    const eventListeners = listenersMap.get(event)!
    eventListeners.push(wrappedListener)
    return eventListeners.length
  }

  function off(event: string, listener: Listener): boolean {
    if (!listenersMap.has(event)) {
      return false
    }
    const eventListeners = listenersMap.get(event)!
    const index = eventListeners.indexOf(listener)
    if (index === -1) {
      return false
    }
    eventListeners.splice(index, 1)
    return true
  }

  function emit(event: string, payload: unknown): unknown[] {
    if (!listenersMap.has(event)) {
      return []
    }
    const eventListeners = listenersMap.get(event)!
    return eventListeners.map(fn => fn(payload))
  }

  function listenerCount(event: string): number {
    if (!listenersMap.has(event)) {
      return 0
    }
    return listenersMap.get(event)!.length
  }

  return { on, once, off, emit, listenerCount }
}

export { createEventEmitter, Listener, EventEmitter }
