interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  reset(key: string): void;
}

interface StateEntry {
  windowStart: number;
  count: number;
  windowId: number;
}

function createRateLimiter(): RateLimiter {
  const state = new Map<string, StateEntry>();

  return {
    allow(key: string, nowMs: number): boolean {
      const MAX_REQUESTS = 3;
      const WINDOW_MS = 1000;

      const windowId = Math.floor(nowMs / WINDOW_MS);

      if (!state.has(key)) {
        state.set(key, { windowStart: nowMs, count: 0, windowId });
      }

      const entry = state.get(key)!;

      // Check if a new window has started (window fully elapsed)
      if (entry.windowId !== windowId) {
        // Fresh window - reset the quota
        state.set(key, { 
          windowStart: nowMs, 
          count: 0, 
          windowId 
        });
      }

      const keyState = state.get(key)!;

      if (keyState.count < MAX_REQUESTS) {
        state.set(key, { ...keyState, count: keyState.count + 1 });
        return true;
      }

      return false;
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}

export { createRateLimiter };
