interface WindowState {
  windowStart: number;
  remaining: number;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const keyStates = new Map<string, WindowState>();

  return {
    allow(key: string, nowMs: number): boolean {
      const state = keyStates.get(key);

      // Check if we need to reset the window based on boundary rule
      if (!state || (nowMs - state.windowStart >= windowMs)) {
        keyStates.set(key, {
          windowStart: nowMs,
          remaining: limit
        });
        return true;
      }

      if (state.remaining > 0) {
        state.remaining--;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = keyStates.get(key);

      // Check if we need to reset according to boundary rule
      if (!state || (nowMs - state.windowStart >= windowMs)) {
        return limit;
      }

      return Math.max(0, state.remaining);
    },

    reset(key: string): void {
      keyStates.delete(key);
    }
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
