export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const entries = new Map<
    string,
    { value: unknown; expiresAt: number }
  >();
  const defaultTtl = 1000;

  return {
    set(
      key: string,
      value: unknown,
      nowMs: number,
      ttlMs?: number,
    ): void {
      const duration = ttlMs ?? defaultTtl;
      const expiresAt = nowMs + duration;
      entries.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        entries.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        entries.delete(key);
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      return entries.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const entry of entries.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
          entries.delete(Array.from(entries.keys()).find((k) => entries.get(k) === entry)!);
        }
      }
      return count;
    },

    clear(): void {
      entries.clear();
    },
  };
}
