const DEFAULT_TTL_MS = 1000;

export function createTtlCache(): TtlCache {
  const entries = new Map<string, Entry>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const actualTtlMs = ttlMs !== undefined ? ttlMs : DEFAULT_TTL_MS;
      const expiresAt = nowMs + actualTtlMs;
      entries.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (!entry) {
        return undefined;
      }
      if (nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      if (!entry) {
        return false;
      }
      if (nowMs >= entry.expiresAt) {
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      return entries.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const [_, entry] of entries) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      entries.clear();
    }
  };
