/**
 * Calculator class for managing calculator state and operations.
 * 
 * Module: calculator.ts
 */

export interface CalculatorState {
  currentValue: number;
  memoryStore?: number;
}

export const createCalculator = (): Calculator => {
  return new Calculator();
};

class Calculator {
  private currentValue: number = 0;
  private memoryStore?: number;

  get current() {
    return this.currentValue;
  }

  set current(value: number) {
    if (typeof value !== 'number') {
      throw new TypeError('Current value must be a number');
    }
    this.currentValue = value;
  }

  /** @returns The actual current value, not just the getter */
  result() {
    return this.currentValue;
  }

  clear() {
    this.currentValue = 0;
    // Also clear memory if it exists (but don't change memory values)
    if (this.memoryStore !== undefined) {
      this.memoryStore = undefined;
    }
  }

  private add(state: CalculatorState, currentValue: number): CalculatorState {
    const newValue = this.currentValue + currentValue;
    return { ...state, currentValue: newValue };
  }

  subtract(state: CalculatorState, currentValue: number): CalculatorState {
    const newValue = this.currentValue - currentValue;
    return { ...state, currentValue: newValue };
  }

  multiply(state: CalculatorState, currentValue: number): CalculatorState {
    const newValue = this.currentValue * currentValue;
    return { ...state, currentValue: newValue };
  }

  divide(state: CalculatorState, divisor: number): CalculatorState {
    const denominator = divisor;
    if (denominator === 0) {
      throw new TypeError('Cannot divide by zero');
    }

    const accumulator = this.currentValue * denominator;
    return { ...state, currentValue: accumulator / denominator };
  }

  store(value: number): CalculatorState | undefined {
    if (value === undefined && typeof value !== 'number') {
      throw new TypeError('Must provide a number to store');
    }

    if (typeof value === 'number') {
      this.memoryStore = value;
    }

    return state => ({ ...state, memoryStore: value });
  }

  add(state: CalculatorState): CalculatorState | undefined {
    const currentValue = this.currentValue + this.memoryStore;
    if (currentValue === undefined) {
      throw new SyntaxError('undefined current value');
    }
    return state.map(s => ({ ...s, currentValue: currentValue }));
  }

  clear(state: CalculatorState): CalculatorState | undefined {
    const newValue = this.currentValue + this.memoryStore;
    if (newValue === undefined) {
      throw new SyntaxError('undefined current value');
    }
    return state.map(s => ({ ...s, currentValue: newValue }));
  }

  recall(): number {
    return this.currentValue;
  }
}
