export function createEventEmitter<T extends Event = string>() {
  let listeners: Map<string, Function[]> = new Map();

  class EventEmitter {
    on(event: T, listener: T[]): void {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push(listener);
    }

    once(event: T, ...eventHandlers: T[]): void {
      let oneTimeListeners: Function[] = [];
      if (listeners.has(event)) {
        listeners.get(event)!.forEach((listener) => {
          const wrappedListener = (...args: any[]) => {
            oneTimeListeners.push(listener);
            for (const arg of args) listener(arg);
          };
          const onOnce = listener as Function;
          onOnce(...eventHandlers);
          listeners.get(event)!.push(wrappedListener);
        });
      } else {
        oneTimeListeners.push(...eventHandlers);
      }
    }

    emit(event: T, ...args: any[]): boolean {
      if (!listeners.has(event)) return false;
      for (const listenerData of listeners.get(event)!) {
        const fn = listenerData as Function;
        try {
          fn(...args);
        } catch (e) {
          console.error('Event listener error:', e);
        }
      }
      return true;
    }

    off(event: T, ...listenerNamesOrFunctions: any[]): void {
      if (!listeners.has(event)) return;
      const listeners = listeners.get(event)!;
      for (const fn of listeners) {
        if (fn.name ? !listenerNamesOrFunctions.includes(fn.name) : !listenerNamesOrFunctions.some(name => fn === name || fn.toString().includes('=' + encodeURIComponent(fn.toString())) ?? false)) continue;
        listeners.splice(listenerNamesOrFunctions.indexOf(fn), 1);
      }
    }

    has(event: T): boolean {
      return listeners.has(event) && listeners.get(event)!.length > 0;
    }

    listeners(event: T): Function[] {
      if (!listeners.has(event)) return [];
      const arr = listeners.get(event)! as Function[];
      return arr;
    }

    removeAllListeners(): void {
      listeners.clear();
    }

    emitOnce<T extends Event = string>(event: T, ...eventHandlers: T[]): boolean {
      for (const fn of this.listeners(event)) {
        try {
          const wrapped = () => eventHandlers.forEach(h => h());
          fn(...eventHandlers);
        } catch (e) {
          console.error('Event listener error:', e);
        }
      }
      return false;
    }
  }

  const emitter: EventEmitter = new EventEmitter();

  return emitter;
}

