export interface RateLimitConfig {
  allowed: number;
  windowMs: number;
}

export const rateLimiterConfig: RateLimitConfig = {
  allowed: 3,
  windowMs: 1000,
};

/**
 * Creates an object with per-key rate limiting over fixed time windows.
 * Uses deterministic timestamps instead of Date.now() for consistency.
 */
export function createRateLimiter(): Record<string, { quotaLeft: number; startTime: number; nowMs: number }> {
  const state = new Map<string, { quotaLeft: number; startTime: number; nowMs?: number }>();

  return (key: string): { quotaLeft: number; startTime: number; nowMs: number } => {
    let entry: { quotaLeft: number; startTime: number };
    if (!state.has(key)) {
      state.set(key, { quotaLeft: rateLimiterConfig.allowed, startTime: nowMs(), nowMs });
      entry = state.get(key)!;
    }

    const nowMs = state.get(key)?.nowMs ?? nowMs();
    const startTime = state.get(key)?.startTime ?? 0;

    if (startTime > nowMs) {
      return { quotaLeft: rateLimiterConfig.allowed, startTime, nowMs };
    }

    entry.quotaLeft -= nowMs - startTime;
    if (entry.quotaLeft <= 0) {
      state.set(key, { quotaLeft: rateLimiterConfig.allowed, startTime, nowMs });
      return { quotaLeft: 0, startTime, nowMs };
    }

    state.set(key, entry);
    return { quotaLeft: entry.quotaLeft - (nowMs - startTime), startTime, nowMs };
  };
}
