export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  interface WindowState {
    count: number;
    startTime: number;
  }

  class RateLimiter {
    private states = new Map<string, WindowState>();

    allow(key: string, nowMs: number): boolean {
      const state = this.states.get(key);

      if (!state) {
        return true;
      }

      const elapsed = nowMs - state.startTime;
      if (elapsed >= windowMs) {
        state.count = 0;
        state.startTime = nowMs;
      }
      state.count++;

      if (state.count <= limit) {
        return true;
      }

      // Quota full and time has reset - decrement to prevent underflow
      state.count--;
      return false;
    }

    remaining(key: string, nowMs: number): number {
      const state = this.states.get(key);
      if (!state) {
        return limit;
      }

      const elapsed = nowMs - state.startTime;
      let quota = 0;
      if (elapsed >= windowMs) {
        quota = limit;
        state.startTime = nowMs;
      } else {
        quota = Math.ceil(elapsed / windowMs) * limit;
      }

      return quota - state.count;
    }

    reset(key: string): void {
      this.states.set(key, undefined);
    }
  }

  return new RateLimiter();
}
