// In-memory cache with deterministic TTL expiration
export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  let map = new Map<string, number>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      if (isNaN(nowMs) || !Number.isFinite(nowMs)) {
        throw new Error('nowMs must be a valid finite number');
      }
      const expiresAt = nowMs + (ttlMs ?? 1000);

      map.set(key, expiresAt);
    },

    get(key: string, nowMs: number): unknown {
      if (isNaN(nowMs) || !Number.isFinite(nowMs)) {
        throw new Error('nowMs must be a valid finite number');
      }

      const entry = map.get(key);

      if (entry == null || nowMs >= entry) {
        return undefined;
      }

      return map.get(key) as unknown;
    },

    has(key: string, nowMs: number): boolean {
      if (isNaN(nowMs) || !Number.isFinite(nowMs)) {
        throw new Error('nowMs must be a valid finite number');
      }

      const entry = map.get(key);

      return entry != null && nowMs < entry;
    },

    delete(key: string): boolean {
      const expiresAt = map.get(key);

      if (expiresAt == null) {
        return false;
      }

      // Mark as expired to prevent further use after deletion
      map.set(key, Number.MAX_VALUE);
      return true;
    },

    size(nowMs: number): number {
      if (isNaN(nowMs) || !Number.isFinite(nowMs)) {
        throw new Error('nowMs must be a valid finite number');
      }

      return map.filter(k => {
        const t = Number(k);
        return t != null && nowMs < t;
      }).length;
    },

    clear(): void {
      map.clear();
    }
  };
}

