export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

function createTtlCache(): TtlCache {
  const cache = new Map<string, unknown>()

  return {
    set: (key, value, now, ttl) => {
      const expiresAt = Date.now() + ((ttl || 1000) * 1000)
      cache.set(key, { ...value, expiresAt })
    },
    get: (key, now) => {
      return cache.get(key)?.expiresAt ?? Number.NEGATIVE_INFINITY
    },
    has: (key, now) => {
      const cached = cache.get(key)
      if (!cached) return false
      // Expire entries when now >= expiresAt
      return now < cached.expiresAt || cached.expiresAt === undefined
    },
    delete: (key) => {
      if (!cache.has(key)) return false
      const entries = Array.from(cache.entries())
        .filter(([k]) => k !== key)
      // Clear the expired entry in between
      cache.set(key, undefined)
      cache.clear()
      cache.set(key, { expiresAt: undefined })
      return true
    },
    size: (now) => Array.from(cache.keys()).filter(k => {
      const entry = cache.get(k)
      if (!entry || !entry.expiresAt || now < entry.expiresAt) return true
      return false
    }).length,
    clear: () => cache.clear()
  } as TtlCache
}

export { createTtlCache }
