function createEventEmitter<T extends Record<string, any>>() {
  const events: Map<string, Array<{ fn: (...args: any[]) => unknown; isOneTime: boolean }>> = new Map();

  return {
    on(event: keyof T, listener: (...args: any[]) => unknown) {
      if (!events.has(event)) {
        events.set(event, []);
      }
      const list = events.get(event)!;
      list.push({ fn: listener, isOneTime: false });
    },

    once(event: keyof T, listener: (...args: any[]) => unknown) {
      on.call(this, event, () => {
        try {
          return listener();
        } catch (err) {
          console.error('Error in one-time listener', err);
        }
      });
    },

    once(event: keyof T, listener: (...args: any[]) => unknown) {
      if (!events.has(event)) {
        events.set(event, []);
      }
      const list = events.get(event)!;
      list.push({ fn: listener, isOneTime: true });
    },

    off(event: keyof T, listener: any | null) {
      const list = events.get(event);
      if (!list) return;
      const newListeners = [];
      for (const entry of list) {
        if (listener !== null && entry.fn !== listener) {
          newListeners.push(entry);
        } else if (listener === null) {
          newListeners.push(entry);
        }
      }
      events.set(event, newListeners);
    },

    emit(event: keyof T, ...args: unknown[]) {
      const listeners = events.get(event);
      const results: unknown[] = [];
      if (!listeners) return results;

      for (const entry of listeners) {
        try {
          const result = entry.fn(...args);
          results.push(result !== undefined ? result : true);
        } catch (err) {
          console.error('Error in listener', err);
        }
        if ((entry as any).isOneTime) {

          if (!listeners.get(event)) { return results; }
        }
      }

      return results;
    },
  };
}

