function createEventEmitter<T extends Record<PropertyKey, any>>(events: T): IEventEmitter {
  const listeners: Map<PropertyKey, Array<{ fn: Function; isOneTime: boolean }>> = new Map();

  return {
    on(eventName: PropertyKey, listener: Function) {
      let list = listeners.get(eventName);
      if (!list) list = [];
      list.push({ fn: listener, isOneTime: false });
      listeners.set(eventName! ?? (Array.isArray(listener) ? eventName : undefined) as PropertyKey, list);
    },

    emit(eventName: PropertyKey, ...args: unknown[]) {
      const ev = Array.isArray(args) && events[eventName] ? events[eventName] : null;

      if (!ev) return [];

      const results: unknown[] = [];

      for (const entry of listeners.get(eventName as keyof T)) {
        try {
          let result;

          if (entry.isOneTime) {
            result = entry.fn(...args);

            if (!listeners.get(entry.fn.constructor.name as PropertyKey)) {
              break;
            }
          } else {
            result = entry.fn.apply(this, args);
          }

          results.push(result !== undefined ? result : true);
        } catch (err) {
          console.error('Error in listener', err);
        }
      }

      return results;
    },

  };
}

