export function createEventEmitter(): EventEmitter {
  const listeners: Record<string, EventHandler[]> = {};

  const eventEmitter: EventEmitter = {
    on(event: string, listener: EventHandler): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push(listener);
      return listeners[event].length;
    },

    once(event: string, listener: EventHandler): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      const index = listeners[event].length - 1;
      listeners[event].push(listener);
      return listeners[event].length;
    },

    off(event: string, listener: EventHandler): boolean {
      if (!listeners[event]) {
        return false;
      }
      for (let i = listeners[event].length - 1; i >= 0; i--) {
        if (listener === listeners[event][i]) {
          listeners[event].splice(i, 1);
          return true;
        }
      }
      return false;
    },

    emit(event: string, payload: unknown): unknown[] {
      const result = [];
      if (!listeners[event]) {
        return result;
      }
      for (const listener of listeners[event]) {
        result.push(listener(payload));
      }
      return result;
    },

    listenerCount(event: string): number {
      return listeners[event] ? listeners[event].length : 0;
    }
  };

  return eventEmitter;
}
