function createRateLimiter(options?: { maxRequests: number; windowMs: number }) {
  const defaultOptions = { maxRequests: 3, windowMs: 1000 };
  const opts = { ...defaultOptions, ...options };
  return new (class RateLimiter {
    private map = new Map<string, { lastRequestTime: number; count: number }>();

    request(key: string, nowMs: number): boolean {
      if (!this.map.has(key)) {
        this.map.set(key, { lastRequestTime: nowMs, count: 0 });
      }
      const state = this.map.get(key)!;
      if (nowMs >= state.lastRequestTime + opts.windowMs) {
        this.map.set(key, { lastRequestTime: nowMs, count: 1 });
        return true;
      }
      if (state.count >= opts.maxRequests) {
        return false;
      }
      state.count += 1;
      this.map.set(key, state);
      return true;
    }

    reset(key: string): void {
      this.map.set(key, { lastRequestTime: Date.now(), count: 0 });
    }
  })();
