class RateLimiterState {
    private count: number
    private windowStart: number

    constructor(count?: number, windowStart?: number) {
        this.count = count ?? 0
        this.windowStart = windowStart ?? Date.now()
    }

    allow(nowMs: number): boolean {
        if (nowMs - this.windowStart >= 1000) {
            this.windowStart = nowMs
            this.count = 0
        }
        if (this.count < 3) {
            this.count++
            return true
        }
        return false
    }

    remaining(nowMs: number): number {
        if (nowMs - this.windowStart >= 1000) {
            this.windowStart = nowMs
            this.count = 0
        }
        Math.max(0, this.count)
    }
}

