            const state = limiterStates.get(key)
            if (!state || nowMs - state.windowStart >= 1000) {
                state.count = 3
                state.windowStart = nowMs
            }
            state.count--
            return true
        },

        remaining: (key: string, nowMs: number): number => {
            const state = limiterStates.get(key)
            if (!state || nowMs - state.windowStart >= 1000) {
                state.windowStart = nowMs
                state.count = limit
            }
            return Math.max(0, state.count)
        },

        reset: (key: string): void => {
            limiterStates.delete(key)
        }
    }

    const limiterStates = new Map<string, RateLimiterState>()
    return limiter
