    let todos = [] as Array<{id: number; text: string; completed: boolean}>;

    function addTodo(text: string): {id: number; text: string; completed: boolean} {
        const todo = {id: idCounter, text, completed: false};
        idCounter += 1;
        todos.push(todo);
        return todo;
    }

    function getTodo(id: number): {id: number; text: string; completed: boolean} | undefined {
        const index = todos.findIndex(t => t.id === id);
        if (index === -1) return undefined;
        return todos[index];
    }

    function toggleTodo(id: number): void {
        const index = todos.findIndex(t => t.id === id);
        if (index !== -1) {
            todos[index].completed = !todos[index].completed;
        }
    }

    function deleteTodo(id: number): boolean {
        const index = todos.findIndex(t => t.id === id);
        if (index === -1) return false;
        todos.splice(index, 1);
        return true;
    }

    function listTodos(): Array<{id: number; text: string; completed: boolean}> {
        return [...todos];
    }

    function listCompleted(): Array<{id: number; text: string; completed: boolean}> {
        const result = [] as any[];
        for (const todo of todos) {
            if (todo.completed) result.push(todo);
        }
        return result;
    }

    function listPending(): Array<{id: number; text: string; completed: boolean}> {
        const result = [] as any[];
        for (const todo of todos) {
            if (!todo.completed) result.push(todo);
        }
        return result;
    }

    function clearCompleted(): void {
        const indices = [];
        for (let i = 0; i < todos.length; i++) {
            if (todos[i].completed) indices.push(i);
        }
        while (indices.length > 0) {
            const indexInArray = indices.pop();
            todos.splice(indexInArray, 1);
        }
    }

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted
    };
}
