export function createTtlCache() {
  return {
    entries: new Map<string, { value: unknown; expiresAt: number }>(),

    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const defaultTtl = Math.max(Math.round(ttlMs), 1000)
      const expiresAt = nowMs + (ttlMs ?? defaultTtl)
      this.entries.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = this.entries.get(key)
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = this.entries.get(key)
      if (!entry) {
        return false
      }
      return nowMs < entry.expiresAt
    },

    delete(key: string): boolean {
      return this.entries.delete(key)
    },

    size(nowMs: number): number {
      let count = 0
      for (const { value, expiresAt } of this.entries.values()) {
        if (!value && nowMs >= expiresAt) {
          continue
        } else {
          count++
        }
      }
      return count
    },

    clear(): void {
      this.entries.clear()
    }
  }
}

