interface TtlCacheState {
  map: Map<string, { value: unknown; expiresAt: number }>
  keys: Set<string>
}

export function createTtlCache(): TtlCache {
  const defaultTtlMs = 1000;
  let state: TtlCacheState = {
    map: new Map(),
    keys: new Set()
  };

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const actualTtl = ttlMs ?? defaultTtlMs;
      const expiresAt = nowMs + (actualTtl > 0 ? actualTtl : 0);
      state.map.set(key, { value, expiresAt });
      state.keys.add(key);
    },
    get(key: string, nowMs: number): unknown {
      const entry = state.map.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) return undefined;
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = state.map.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) return false;
      return true;
    },
    delete(key: string): boolean {
      const removed = state.keys.delete(key);
      state.map.delete(key);
      return removed;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const key of state.keys) {
        const entry = state.map.get(key);
        if (!entry || nowMs >= entry.expiresAt) continue;
        count++;
      }
      return count;
    },
    clear(): void {
      state.keys.clear();
      state.map.clear();
    }
  };
}
