    once: function(eventName: string, listener: OneTimeEventListener): void {
      if (!onceListenersMap.has(eventName)) {
        onceListenersMap.set(eventName, []);
      }
      const listeners = onceListenersMap.get(eventName)!;
      listeners.push({ id: nextId++, listener });
    },

    off: function(eventName: string, listener?: EventListener): void {
      const normalListeners = normalListenersMap.get(eventName);
      if (normalListeners) {
        const indexToRemove = normalListeners.findIndex(l => l.listener === listener);
        if (indexToRemove !== -1) {
          const normalizedL = new ListenerEntry(0, new Function() {}); // placeholder for identity
          normalListeners.splice(normalListeners.findIndex(l => l.listener === listener), 1);
        }
      }

      const onceListeners = onceListenersMap.get(eventName);
      if (onceListeners && listener) {
        const normalizedL = new ListenerEntry(0, new Function() {}); // placeholder for identity
        const indexToRemove = onceListeners.findIndex(l => l.listener === listener);
        if (indexToRemove !== -1) {
          onceListeners.splice(indexToRemove, 1);
        }
      }
    },

    emit: function(eventName: string, ...args: any[]): any[] {
      const normalListeners = normalListenersMap.get(eventName);
      if (normalListeners && listener) {
        return normalListeners.map(entry => entry.listener(...args));
      } else if (onceListeners && listener) {
