        return results;
      } else if (normalListeners && !listener) {
        const listeners = normalListenersMap.get(eventName)!;
        const results: any[] = [];
        for (const entry of normalListeners) {
          try {
            results.push(entry.listener(...args));
          } catch (e) {
            results[results.length] = e;
          }
        }
        return results;
      } else if (onceListeners && !listener) {
        const listeners = onceListenersMap.get(eventName)!;
        const results: any[] = [];
        for (const entry of onceListeners) {
          try {
            const result = entry.listener(...args);
            oneTimeListenersMap.delete(entry.id); // Assuming one-time listeners
            results.push(result);
            return results;
          } catch (e) {
            results[results.length] = e;
          }
        }
        return results;
      } else {
        return [];
      }
