    listeners: function(eventName: string): EventListener[] {
      // Returns all listeners combined in registration order
      const normalListeners = normalListenersMap.get(eventName) || [];
      const onceListeners = onceListenersMap.get(eventName) || [];

      const results: EventListener[] = [];
      for (const entry of normalListeners) {
