type Listener = (payload: unknown) => unknown

export interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const events = new Map<string, Array<Listener>>();

  return {
    on(event: string, listener: Listener): number {
      if (!events.has(event)) {
        events.set(event, []);
      }
      const listeners = events.get(event)!;
      listeners.push(listener);
      return listeners.length;
    },

    once(event: string, listener: Listener): number {
      let removedSelf = false;
      const wrappedListener = (payload: unknown) => {
        removedSelf = true;
        listener(payload);
      };
      if (!events.has(event)) {
        events.set(event, []);
      }
      const listeners = events.get(event)!;
      listeners.push(wrappedListener);
      return listeners.length;
    },

    off(event: string, listener: Listener): boolean {
      const listeners = events.get(event);
      if (!listeners) {
        return false;
      }
      const index = listeners.indexOf(listener);
      if (index === -1) {
        return false;
      }
      listeners.splice(index, 1);
      return true;
    },

    emit(event: string, payload: unknown): unknown[] {
      const listeners = events.get(event);
      if (!listeners) {
        return [];
      }

      const results: unknown[] = listeners.map(listener => {
        let result: unknown;
        if (listener === removedSelf) {
          // Extract original function before it gets called again
          result = listener(payload);
        } else {
          // Re-attach self-removal after emit but don't re-run immediately
          // Actually, we need to check if this is a wrapper and unwrap it
          const callResult = listener(payload);
          if (callResult !== undefined) {
            return callResult;
          }
        }
        return true;
      });

      return listeners.length > 0 ? results : [];
    },

    listenerCount(event: string): number {
      const listeners = events.get(event);
      return listeners ? listeners.length : 0;
    },
  };
}
