        states.set(key, state)
        return true
      }

      const windowExpired = nowMs >= state.windowEndMs

      if (windowExpired) {
        state.count = 1
        state.windowEndMs = nowMs + WINDOW_SIZE_MS
        states.set(key, state)
        return true
      }

      state.count += 1

      if (state.count <= MAX_REQUESTS) {
        return true
      } else {
        return false
      }
    },

    reset: (key: string): void => {
      states.delete(key)
    }
  }
}
