export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const state: Map<string, number[]> = new Map();

  return {
    allow(key: string, nowMs: number): boolean {
      let requests: number[] = state.get(key);

      if (!requests) {
        createFreshWindow(key);
        requests = getRequests(key);
      }

      const oldest = requests.length > 0 ? Math.min(...requests) : Infinity;
      const cutoff = nowMs - windowMs;

      if (oldest < cutoff) {
        while (requests.length > 0 && requests[0] < cutoff) {
          requests.shift();
        }
        state.set(key, requests);
      } else {
        createFreshWindow(key);
        requests = getRequests(key);
      }

      return true;
    },

    remaining(key: string, nowMs: number): number {
      let requests: number[] = state.get(key);

      if (!requests || requests.length === 0) {
        return limit;
      }

      const cutoff = nowMs - windowMs;

      // Clean expired requests and re-fetch to get current valid count
      while (requests.length > 0 && requests[0] < cutoff) {
        requests.shift();
      }

      state.set(key, [...requests]);

      return Math.max(limit - requests.length, 0);
    },

    reset(key: string): void {
      state.delete(key);
    }
  };

  function getRequests(key: string) {
    let requests = state.get(key);
    if (!requests) {
      requests = [];
      state.set(key, requests);
    }
    return requests;
  }

  function createFreshWindow(key: string): void {
    const requests: number[] = [];
    state.set(key, requests);
  }
}
