export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const store: Map<string, { value: unknown; expiresAt: number }> = new Map()

  function expiresAt(key: string, nowMs: number, ttlMs?: number): number {
    return nowMs + (ttlMs ?? 1000)
  }

  function isExpired(entry: { value: unknown; expiresAt: number }, nowMs: number): boolean {
    return nowMs >= entry.expiresAt
  }

  return {
    set(key, value, nowMs, ttlMs = undefined) {
      const entry = { value, expiresAt: expiresAt(key, nowMs, ttlMs) }
      store.set(key, entry)
    },

    get(key, nowMs) {
      const entry = store.get(key)
      if (isExpired(entry!, nowMs)) {
        store.delete(key)
        return undefined
      }
      return entry!.value
    },

    has(key, nowMs) {
      const entry = store.get(key)
      if (!entry || isExpired(entry, nowMs)) {
        store.delete(key)
        return false
      }
      return true
    },

    delete(key) {
      return store.delete(key)
    },

    size(nowMs) {
      let count = 0
      for (const entry of store.values()) {
        if (!isExpired(entry, nowMs)) {
          count++
        }
      }
      return count
    },

    clear() {
      store.clear()
    }
  }
}
