export function createTtlCache(): TtlCache {
  const store = new Map<string, { value: unknown; expiresAt: number }>()
  const defaultTtlMs = 1000

  function isExpired(expiresAt: number, nowMs: number): boolean {
    return nowMs >= expiresAt
  }

  function isEntryValid(entry: { value: unknown; expiresAt: number } | undefined, nowMs: number): boolean {
    return entry !== undefined && !isExpired(entry.expiresAt, nowMs)
  }

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const expiresAt = nowMs + (ttlMs ?? defaultTtlMs)
      store.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = store.get(key)
      if (entry === undefined) {
        return undefined
      }
      if (isExpired(entry.expiresAt, nowMs)) {
        store.delete(key)
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = store.get(key)
      if (entry === undefined) {
        return false
      }
      return !isExpired(entry.expiresAt, nowMs)
    },

    delete(key: string): boolean {
      return store.delete(key)
    },

    size(nowMs: number): number {
      let count = 0
      for (const entry of store.values()) {
        if (!isExpired(entry.expiresAt, nowMs)) {
          count++
        }
      }
      return count
    },

    clear(): void {
      store.clear()
    }
  }
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}
