type EventEmitterListener = (...args: unknown[]) => unknown;

export function createEventEmitter() {
  const listeners = new Map<string, Array<EventEmitterListener>>();
  const onceSet = new Map<string, Set<EventEmitterListener>>();

  return {
    on(event: string, listener: EventEmitterListener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
        onceSet.set(event, new Set());
      }
      listeners.get(event)!.push(listener);
    },

    once(event: string, listener: EventEmitterListener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
        onceSet.set(event, new Set());
      }
      listeners.get(event)!.push(listener);
      onceSet.get(event)!.add(listener);
    },

    off(event: string, listener: EventEmitterListener) {
      const eventListeners = listeners.get(event);
      if (eventListeners) {
        const index = eventListeners.indexOf(listener);
        if (index !== -1) {
          eventListeners.splice(index, 1);
          onceSet.get(event)?.delete(listener);
          if (eventListeners.length === 0) {
            listeners.delete(event);
            onceSet.delete(event);
          }
        }
      }
    },

    emit(event: string, ...args: unknown[]): Array<unknown> {
      const returnValues: Array<unknown> = [];
      const eventListeners = listeners.get(event) || [];

      for (const listener of eventListeners) {
        const result = listener(...args);
        returnValues.push(result);
        if (onceSet.get(event)?.has(listener)) {
          onceSet.get(event)!.delete(listener);
        }
      }

      return returnValues;
    },
  };
}
