type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ listener: Listener; once: boolean }>>()

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      listeners.get(event)!.push({ listener, once: false })
      return listeners.get(event)!.length
    },

    once(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      listeners.get(event)!.push({ listener, once: true })
      return listeners.get(event)!.length
    },

    off(event, listener) {
      const eventListeners = listeners.get(event)
      if (!eventListeners || eventListeners.length === 0) {
        return false
      }
      const index = eventListeners.findIndex(
        (entry) => entry.listener === listener
      )
      if (index === -1) {
        return false
      }
      eventListeners.splice(index, 1)
      return true
    },

    emit(event, payload) {
      const eventListeners = listeners.get(event)
      if (!eventListeners || eventListeners.length === 0) {
        return []
      }
      const results: unknown[] = []
      let i = 0
      while (i < eventListeners.length) {
        const { listener, once } = eventListeners[i]
        const result = listener(payload)
        results.push(result)
        if (once) {
          eventListeners.splice(i, 1)
        } else {
          i++
        }
      }
      return results
    },

    listenerCount(event) {
      const eventListeners = listeners.get(event)
      return eventListeners ? eventListeners.length : 0
    }
  }
}
