interface RateLimiterState {
  windowStart: number
  count: number
}

const LIMIT = 3
const WINDOW_MS = 1000

export function createRateLimiter(): RateLimiter {
  const stateMap = new Map<string, RateLimiterState>()

  return {
    allow(key: string, nowMs: number): boolean {
      const existing = stateMap.get(key)

      let windowStart = existing?.windowStart
      if (windowStart === undefined || nowMs - windowStart >= WINDOW_MS) {
        windowStart = nowMs
      }

      const count = existing?.count ?? 0

      if (count < LIMIT) {
        stateMap.set(key, { windowStart: windowStart, count: count + 1 })
        return true
      }

      stateMap.set(key, { windowStart: windowStart, count: count })
      return false
    },

    remaining(key: string, nowMs: number): number {
      const existing = stateMap.get(key)

      let count = 0
      if (existing && nowMs - existing.windowStart < WINDOW_MS) {
        count = existing.count
      }

      const remainingQuota = LIMIT - count
      return remainingQuota < 0 ? 0 : remainingQuota
    },

    reset(key: string): void {
      stateMap.delete(key)
    }
  }
}
