  divide(n: number): Calculator
  clear(): Calculator
  result(): number
  memoryStore(): Calculator
  memoryRecall(): number
  memoryClear(): Calculator
  memoryAdd(): Calculator
}

export function createCalculator(): Calculator {
  let currentValue = 0
  let memory = 0

  return {
    add(n) {
      currentValue += n
      return this
    },
    subtract(n) {
      currentValue -= n
      return this
    },
    multiply(n) {
      currentValue *= n
      return this
    },
    divide(n) {
      if (n !== 0) {
        currentValue /= n
      }
      return this
    },
    clear() {
      currentValue = 0
      return this
    },
    result() {
      return currentValue
    },
    memoryStore() {
      memory = currentValue
      return this
    },
    memoryRecall() {
      return memory
    },
    memoryClear() {
      memory = 0
      return this
    },
    memoryAdd() {
      memory += currentValue
      return this
    }
  }
}
