type Listener = () => unknown;
type EventMap = Map<string, Array<Listener>>;

interface EventEmitter {
  on(event: string, listener: Listener): void;
  once(event: string, listener: Listener): void;
  off(event: string, listener: Listener): void;
  emit(event: string): unknown[];
}

function createEventEmitter(): EventEmitter {
  const listeners: EventMap = new Map();
  const oneTimeListeners: EventMap = new Map();

  function ensureListeners(event: string) {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
  }

  function ensureOneTimeListeners(event: string) {
    if (!oneTimeListeners.has(event)) {
      oneTimeListeners.set(event, []);
    }
  }

  return {
    on(event: string, listener: Listener): void {
      ensureListeners(event);
      listeners.get(event)!.push(listener);
    },

    once(event: string, listener: Listener): void {
      const wrapped = (): unknown => {
        const index = oneTimeListeners.get(event)?.indexOf(wrapped);
        if (index !== undefined && index !== -1) {
          oneTimeListeners.get(event)!.splice(index, 1);
        }
        return listener();
      };
      ensureOneTimeListeners(event);
      oneTimeListeners.get(event)!.push(wrapped as Listener);
    },

    off(event: string, listener: Listener): void {
      const eventListeners = listeners.get(event);
      if (eventListeners) {
        const index = eventListeners.indexOf(listener);
        if (index !== -1) {
          eventListeners.splice(index, 1);
        }
      }
    },

    emit(event: string): unknown[] {
      const results: unknown[] = [];

      const eventListeners = listeners.get(event);
      if (eventListeners) {
        for (const listener of eventListeners) {
          try {
            const result = listener();
            results.push(result);
          } catch {
            // Ignore listener errors
          }
        }
      }

      const oneTimeEventListeners = oneTimeListeners.get(event);
      if (oneTimeEventListeners) {
        for (const listener of oneTimeEventListeners) {
          try {
            const result = listener();
            results.push(result);
          } catch {
            // Ignore listener errors
          }
        }
        oneTimeListeners.delete(event);
      }

      return results;
    }
  };
}

export { createEventEmitter };
