export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ listener: Listener; once: boolean }>>()

  return {
    on(event: string, listener: Listener): number {
      const list = listeners.get(event) || []
      list.push({ listener, once: false })
      listeners.set(event, list)
      return list.length
    },

    once(event: string, listener: Listener): number {
      const list = listeners.get(event) || []
      list.push({ listener, once: true })
      listeners.set(event, list)
      return list.length
    },

    off(event: string, listener: Listener): boolean {
      const list = listeners.get(event)
      if (!list) return false

      const index = list.findIndex(item => item.listener === listener)
      if (index === -1) return false

      list.splice(index, 1)

      if (list.length === 0) {
        listeners.delete(event)
      }

      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      const list = listeners.get(event)
      if (!list) return []

      const results: unknown[] = []
      let i = 0

      while (i < list.length) {
        const item = list[i]

        if (item.once) {
          results.push(item.listener(payload))
          list.splice(i, 1)
        } else {
          results.push(item.listener(payload))
          i++
        }
      }

      if (list.length === 0) {
        listeners.delete(event)
      }

      return results
    },

    listenerCount(event: string): number {
      const list = listeners.get(event)
      return list ? list.length : 0
    }
  }
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}
