type RateLimiterState = {
  windowStart: number;
  requestCount: number;
};

interface CreatedRateLimiter {
  isAllowed(key: string, nowMs: number): boolean;
  reset(key: string): void;
  peekUsage(key: string, nowMs: number): { count: number; windowEnd: number };
}

function createRateLimiter(): CreatedRateLimiter {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;
  const stateMap = new Map<string, RateLimiterState>();

  function isAllowed(key: string, nowMs: number): boolean {
    const keyState = stateMap.get(key);
    const windowElapsed = !keyState || (nowMs - keyState.windowStart) >= WINDOW_MS;

    if (windowElapsed) {
      stateMap.set(key, { windowStart: nowMs, requestCount: 0 });
      return true;
    }

    if (keyState.requestCount < MAX_REQUESTS) {
      keyState.requestCount++;
      return true;
    }

    return false;
  }

  function reset(key: string): void {
    stateMap.delete(key);
  }

  function peekUsage(key: string, nowMs: number): { count: number; windowEnd: number } {
    const keyState = stateMap.get(key);
    if (!keyState || (nowMs - keyState.windowStart) >= WINDOW_MS) {
      return { count: 0, windowEnd: nowMs + WINDOW_MS };
    }

    return {
      count: keyState.requestCount,
      windowEnd: keyState.windowStart + WINDOW_MS
    };
  }

  return { isAllowed, reset, peekUsage };
}

export { createRateLimiter };
