export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000

  const state = new Map<string, { windowStart: number; count: number }>()

  return {
    allow(key: string, nowMs: number): boolean {
      const existing = state.get(key)

      // Check if we need to start a fresh window
      if (existing && nowMs - existing.windowStart >= windowMs) {
        existing.windowStart = nowMs
        existing.count = 0
      }

      const entry = state.get(key)

      if (!entry) {
        state.set(key, { windowStart: nowMs, count: 1 })
        return true
      }

      if (entry.count < limit) {
        entry.count++
        return true
      }

      return false
    },
    remaining(key: string, nowMs: number): number {
      const existing = state.get(key)

      // Check if we need to start a fresh window
      if (existing && nowMs - existing.windowStart >= windowMs) {
        return limit
      }

      const count = existing?.count ?? 0
      return Math.max(0, limit - count)
    },
    reset(key: string): void {
      state.delete(key)
    }
  }
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
