export function createTodoApp() {
  let nextId = 1;
  const todos: Array<{ id: number, text: string, completed: boolean }> = [];

  function addTodo(text: string): { id: number, text: string, completed: boolean } {
    const todo = { id: nextId++, text, completed: false };
    todos.push(todo);
    return todo;
  }

  function getTodo(id: number): { id: number, text: string, completed: boolean } | undefined {
    for (const todo of todos) {
      if (todo.id === id) {
        return todo;
      }
    }
    return undefined;
  }

  function toggleTodo(id: number): void {
    for (const todo of todos) {
      if (todo.id === id) {
        todo.completed = !todo.completed;
        return;
      }
    }
  }

  function deleteTodo(id: number): boolean {
    for (let i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos.splice(i, 1);
        return true;
      }
    }
    return false;
  }

  function listTodos(): Array<{ id: number, text: string, completed: boolean }> {
    const result: Array<{ id: number, text: string, completed: boolean }> = [];
    for (const todo of todos) {
      result.push(todo);
    }
    return result;
  }

  function listCompleted(): Array<{ id: number, text: string, completed: boolean }> {
    const result: Array<{ id: number, text: string, completed: boolean }> = [];
    for (const todo of todos) {
      if (todo.completed) {
        result.push(todo);
      }
    }
    return result;
  }

  function listPending(): Array<{ id: number, text: string, completed: boolean }> {
    const result: Array<{ id: number, text: string, completed: boolean }> = [];
    for (const todo of todos) {
      if (!todo.completed) {
        result.push(todo);
      }
    }
    return result;
  }

  function clearCompleted(): void {
    const remaining: Array<{ id: number, text: string, completed: boolean }> = [];
    for (const todo of todos) {
      if (!todo.completed) {
        remaining.push(todo);
      }
    }
    for (let i = 0; i < todos.length; i++) {
      if (!remaining.includes(todos[i])) {
        todos.splice(i, 1);
        i--;
      }
    }
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
