interface Todo {
  id: number
  text: string
  completed: boolean
}

interface TodoApp {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

function createTodoApp(): TodoApp {
  let nextId = 1
  const todos: Todo[] = []

  return {
    addTodo(text) {
      const todo: Todo = { id: nextId++, text, completed: false }
      todos.push(todo)
      return todo
    },

    getTodo(id) {
      return todos.find((t) => t.id === id)
    },

    toggleTodo(id) {
      const todo = todos.find((t) => t.id === id)
      if (todo) {
        todo.completed = !todo.completed
      }
    },

    deleteTodo(id) {
      const index = todos.findIndex((t) => t.id === id)
      if (index !== -1) {
        todos.splice(index, 1)
        return true
      }
      return false
    },

    listTodos() {
      return [...todos]
    },

    listCompleted() {
      return todos.filter((t) => t.completed)
    },

    listPending() {
      return todos.filter((t) => !t.completed)
    },

    clearCompleted() {
      const completedIds = todos
        .filter((t) => t.completed)
        .map((t) => t.id)

      for (let i = todos.length - 1; i >= 0; i--) {
        if (todos[i].completed && completedIds.includes(todos[i].id)) {
          todos.splice(i, 1)
        }
      }
    },
  }
}

export { createTodoApp }
